// === Tab: mySketch ===
let N =50;
particle[] p=new particle [N] ;
let dt =0.5;
let thres = 200;
color [] cols = {"#ff7605","#ff6105","#ff1205","#ffea05"};

function setup(){
	createCanvas(1024, 768);
  background(0);

  for(i=0; i<N;++i){ 
    p[i] = new particle();
    p[i].move();
  }
}

function draw(){
  fill(255);
  stroke(255);
  strokeWeight(2);

  for(i=0; i<N;++i){
    p[i].show();
    p[i].move();
    p[i].periodic();
  }
  connect ();    
}

class particle{
  loc;
  Vel;
  theta ;
  rad;
  col;
  dtval;

  constructor(){
    loc= new PVector ( random(width) ,random(height));
    Vel = new PVector ( random(-1,1) ,random(-1,1));
    theta = random (TWO_PI);
    rad= random ( 2,10);
    col= cols[int(random(cols.length))];
    dtval = random (0,0.5)*0.1;
  }

  function show(){
    fill(col);
    stroke (255,1);
    ellipse( loc.x , loc.y, 1, 1);
  }

  function move() {
    loc.x += Vel.x*dt;
    loc.y += Vel.y*dt;
    Vel.x = cos(theta)*rad;
    Vel.y = sin(theta)*rad;
    theta += random (-1,1)*0.2; 
  }

  function periodic(){
    loc.x = ( loc.x + width ) % width;
    loc.y = ( loc.y + height )% height;
  }
}

function connect(){
  stroke (255,20);
  for ( i =0; i<N;++i){
    for ( j=0; j<N;++j){
      if (  pow ( p[i].loc.x-p[j].loc.x,2) + pow(p[i].loc.y-p[j].loc.y,2)< pow(thres,2) ){
        fill(p[i].col);
        stroke( p[i].col, 75 ) ;
        line ( p[i].loc.x,p[i].loc.y,p[j].loc.x,p[j].loc.y);
      }
    }
  }
}

